export async function createCalendarEventAction(formData: FormData): Promise<CalendarActionResult> {
  const input = Object.fromEntries(formData.entries());
  try {
    const issued = await issueCalendarEventBrowserOperation(input);
    if (issued.status !== "pending") return toActionResult(issued);
    return toActionResult(await submitCalendarEventBrowserOperation(input));
  } catch (error) {
    const failure = browserOperationFailureResult(input.operationId, error);
    if (failure) return toActionResult(failure);
    throw error;
  }
}

export async function startAutomatedBackupScheduler() {
  const state = getState();
  if (state.started || !automatedBackupConfig.enabled) return state;
  state.started = true;

  const tick = async () => {
    if (state.running) return;
    state.running = true;
    try {
      await runAutomatedBackupScan(new Date(), automatedBackupConfig);
    } catch (error) {
      console.error("backup_scheduler_tick_failed", sanitizeAutomatedBackupError(error));
    } finally {
      state.running = false;
    }
  };

  try {
    await reconcileAutomatedBackupStorage(automatedBackupConfig);
  } catch (error) {
    console.error("backup_scheduler_reconcile_failed", sanitizeAutomatedBackupError(error));
  }
  await tick();

  state.timer = setInterval(() => {
    void tick();
  }, automatedBackupConfig.pollMinutes * 60 * 1000);
  state.timer.unref?.();
  return state;
}

export async function startIntegrityScheduler() {
  const state = getState();
  if (state.started || !integrityConfig.enabled) return state;
  state.started = true;

  const tick = async () => {
    if (state.running) return;
    state.running = true;
    try {
      const result = await runScheduledIntegritySuite(prisma);
      if (!result.executed) return;
      const { report } = result;
      console.info("integrity_scheduler_result", report.status, report.version, report.findings.length, report.evidenceFingerprint);
    } catch {
      console.error("integrity_scheduler_result", "incomplete");
    } finally {
      state.running = false;
    }
  };

  await tick();
  state.timer = setInterval(() => {
    void tick();
  }, integrityConfig.intervalHours * 60 * 60 * 1000);
  state.timer.unref?.();
  return state;
}

